source='''def _components(grid):
    rows, cols = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(rows):
        for c in range(cols):
            if not grid[r][c] or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for a, b in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= a < rows and 0 <= b < cols and grid[a][b] and (a, b) not in seen:
                        seen.add((a, b))
                        stack.append((a, b))
            components.append(cells)
    return components


def _object_grid(grid, cells):
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    return [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]


def transform(grid):
    objects = sorted(_components(grid), key=len, reverse=True)[:2]
    larger, smaller = [_object_grid(grid, obj) for obj in objects]
    height = max(len(larger), len(smaller))
    width = max(max(map(len, larger)), max(map(len, smaller)))
    remaining = {
        (r, c)
        for r in range(height)
        for c in range(width)
        if (larger[r][c] if r < len(larger) and c < len(larger[r]) else 0)
        and not (smaller[r][c] if r < len(smaller) and c < len(smaller[r]) else 0)
    }
    groups = []
    while remaining:
        start = remaining.pop()
        group = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for neighbor in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if neighbor in remaining:
                    remaining.remove(neighbor)
                    group.add(neighbor)
                    stack.append(neighbor)
        if len(group) > 1:
            groups.append(group)
    cells = set().union(*groups)
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    return [[8 if (r, c) in cells else 0 for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
